def f(n):
    if n == 0:
        return 0 # Should not happen for positive integers
    m = 0
    temp_n = n
    while temp_n > 0 and temp_n % 2 == 0:
        m += 1
        temp_n //= 2
    return temp_n

def check_condition(v, u):
    differences = []
    for k in range(v):
        d = f(u + k + v) - f(u + k)
        differences.append(d)

    all_multiple_of_4 = all(d % 4 == 0 for d in differences)
    return all_multiple_of_4, differences

v_values = [1, 2, 3]
u_values = range(1, 11)

findings = {}

for v in v_values:
    found_u = []
    for u in u_values:
        works, diffs = check_condition(v, u)
        if works:
            found_u.append(u)
    findings[v] = found_u

print(findings)

